package com.cyberpath.learning;
import android.app.*;
import android.app.job.*;
import android.appwidget.AppWidgetManager;
import android.content.*;
import android.content.pm.PackageManager;
import android.database.Cursor;
import android.net.Uri;
import android.os.Build;
import android.provider.DocumentsContract;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.concurrent.*;

/** Phone-only services. No account, server, or broad storage permission is required. */
public final class NativeServices {
 public static final String PREFS="lw-phone",CHANNEL="lw-study",REMIND="com.cyberpath.learning.REMIND";
 private static final int PERIODIC_JOB=410,KICK_JOB=411,REMINDER_REQUEST=310;
 public static final ScheduledExecutorService IO=Executors.newSingleThreadScheduledExecutor();
 private static ScheduledFuture<?> pending;
 public static SharedPreferences prefs(Context c){String id=ProfileFiles.active(c);return c.getSharedPreferences("default".equals(id)?PREFS:PREFS+"--"+id,Context.MODE_PRIVATE);}
 private static JSONArray array(String text){try{return new JSONArray(text);}catch(Exception e){return new JSONArray();}}
 public static boolean notificationsAllowed(Context c){NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=33&&c.checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)return false;if(!nm.areNotificationsEnabled())return false;NotificationChannel channel=nm.getNotificationChannel(CHANNEL);return channel==null||channel.getImportance()!=NotificationManager.IMPORTANCE_NONE;}
 public static void channels(Context c){NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);NotificationChannel ch=new NotificationChannel(CHANNEL,"Daily study reminders",NotificationManager.IMPORTANCE_DEFAULT);ch.setDescription("Your chosen study time and next learning topic");nm.createNotificationChannel(ch);}
 public static JSONObject reminder(Context c)throws JSONException{SharedPreferences p=prefs(c);return new JSONObject().put("enabled",p.getBoolean("reminderEnabled",false)).put("time",p.getString("reminderTime","19:00")).put("days",array(p.getString("reminderDays","[1,2,3,4,5,6]"))).put("courseId",p.getString("reminderCourse","active"));}
 public static void configureReminder(Context c,String raw)throws Exception{JSONObject r=new JSONObject(raw);String time=r.getString("time"),course=r.optString("courseId","active");if(!time.matches("([01][0-9]|2[0-3]):[0-5][0-9]"))throw new IllegalArgumentException("Choose a valid reminder time");JSONArray days=r.getJSONArray("days");if(days.length()==0||days.length()>7)throw new IllegalArgumentException("Choose reminder days");for(int i=0;i<days.length();i++)if(days.getInt(i)<1||days.getInt(i)>7)throw new IllegalArgumentException("Invalid reminder day");prefs(c).edit().putBoolean("reminderEnabled",r.getBoolean("enabled")).putString("reminderTime",time).putString("reminderDays",days.toString()).putString("reminderCourse",course).apply();scheduleReminder(c);}
 public static void scheduleReminder(Context c){try{AlarmManager alarms=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);Intent intent=new Intent(c,ReminderReceiver.class).setAction(REMIND);PendingIntent pi=PendingIntent.getBroadcast(c,REMINDER_REQUEST,intent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);alarms.cancel(pi);JSONObject r=reminder(c);if(!r.getBoolean("enabled")){prefs(c).edit().remove("reminderNext").apply();return;}Set<Integer> days=new HashSet<>();JSONArray a=r.getJSONArray("days");for(int i=0;i<a.length();i++)days.add(a.getInt(i));long next=ReminderSchedule.next(r.getString("time"),days,ZonedDateTime.now()).toInstant().toEpochMilli();alarms.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,next,pi);prefs(c).edit().putLong("reminderNext",next).remove("reminderError").apply();}catch(Exception e){prefs(c).edit().putString("reminderError","The reminder could not be scheduled: "+e.getMessage()).apply();}}
 public static JSONObject selectedCourse(Context c,String requested){return selectedCourse(AppFiles.workspace(c),requested);}
 public static JSONObject selectedCourse(JSONObject workspace,String requested){JSONObject summary=workspace.optJSONObject("companionData");if(summary==null)return new JSONObject();JSONArray courses=summary.optJSONArray("courses");if(courses==null)return new JSONObject();String id="active".equals(requested)?summary.optString("activeCourseId"):requested;for(int i=0;i<courses.length();i++){JSONObject course=courses.optJSONObject(i);if(course!=null&&id.equals(course.optString("id")))return course;}return courses.optJSONObject(0)==null?new JSONObject():courses.optJSONObject(0);}
 public static PendingIntent openWork(Context c,String course,int request){Intent intent=new Intent(c,MainActivity.class).putExtra("lwCourseId",course).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);return PendingIntent.getActivity(c,request,intent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 public static void notifyStudy(Context c,boolean test){if(!test){JSONObject learning=AppFiles.workspace(c).optJSONObject("learning"),holiday=learning==null?null:learning.optJSONObject("holiday");String today=java.time.LocalDate.now().toString();if(holiday!=null&&!holiday.optString("from").isEmpty()&&holiday.optString("from").compareTo(today)<=0&&holiday.optString("to").compareTo(today)>=0)return;}channels(c);if(!notificationsAllowed(c))return;JSONObject course=selectedCourse(c,prefs(c).getString("reminderCourse","active"));String title=course.optString("title","Your learning studio"),topic=course.optString("nextTask",course.optString("nextTopic","Open Work to choose your next topic"));Notification notification=new Notification.Builder(c,CHANNEL).setSmallIcon(R.drawable.notification_leaf).setContentTitle(test?"Your study reminder is ready":"Time for "+title).setContentText(topic).setStyle(new Notification.BigTextStyle().bigText(topic+"\nOpen Work and take one small step.")).setContentIntent(openWork(c,course.optString("id",""),321)).setLocalOnly(!prefs(c).getBoolean("watchMirror",true)).setAutoCancel(true).setVisibility(Notification.VISIBILITY_PRIVATE).build();((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).notify(test?902:901,notification);}
 public static void bootstrap(Context c){channels(c);FocusNotification.sync(c);scheduleReminder(c);scheduleBackups(c);LearningWidget.updateAll(c);}
 public static void onWorkspaceSaved(Context context){Context c=context.getApplicationContext();synchronized(NativeServices.class){if(pending!=null)pending.cancel(false);pending=IO.schedule(()->{LearningWidget.updateAll(c);maybeBackup(c,false);},3,TimeUnit.SECONDS);}if(prefs(c).getBoolean("backupEnabled",false)&&"changes".equals(prefs(c).getString("backupFrequency","daily")))scheduleKick(c);}
 private static boolean folderGranted(Context c){String value=prefs(c).getString("backupFolder","");if(value.isEmpty())return false;for(UriPermission permission:c.getContentResolver().getPersistedUriPermissions())if(value.equals(permission.getUri().toString())&&permission.isReadPermission()&&permission.isWritePermission())return true;return false;}
 public static void chooseFolderResult(Context c,Uri uri,int flags)throws Exception{c.getContentResolver().takePersistableUriPermission(uri,flags&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION));String name="Chosen backup folder";Uri doc=DocumentsContract.buildDocumentUriUsingTree(uri,DocumentsContract.getTreeDocumentId(uri));try(Cursor cursor=c.getContentResolver().query(doc,new String[]{DocumentsContract.Document.COLUMN_DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst())name=cursor.getString(0);}String previous=prefs(c).getString("backupFolder","");SharedPreferences.Editor edit=prefs(c).edit().putString("backupFolder",uri.toString()).putString("backupFolderName",name).putBoolean("backupEnabled",true).remove("backupError");if(!previous.equals(uri.toString()))edit.putString("backupHistory","[]").putLong("backupLastAt",0).putLong("backupRevision",-1);edit.apply();if(!previous.isEmpty()&&!previous.equals(uri.toString()))try{c.getContentResolver().releasePersistableUriPermission(Uri.parse(previous),Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);}catch(Exception ignored){}scheduleBackups(c);IO.execute(()->maybeBackup(c,true));}
 public static void configureBackup(Context c,String raw)throws Exception{JSONObject b=new JSONObject(raw);String frequency=b.getString("frequency");int keep=b.getInt("keep");if(!Arrays.asList("daily","hourly","changes").contains(frequency)||!Arrays.asList(7,14,30,60).contains(keep))throw new IllegalArgumentException("Choose a supported backup schedule and history size");boolean enabled=b.optBoolean("enabled",false);if(enabled&&!folderGranted(c))throw new IllegalArgumentException("Choose a backup folder first");prefs(c).edit().putBoolean("backupEnabled",enabled).putString("backupFrequency",frequency).putInt("backupKeep",keep).apply();scheduleBackups(c);if(enabled)IO.execute(()->maybeBackup(c,false));}
 private static void scheduleKick(Context c){JobInfo job=new JobInfo.Builder(KICK_JOB,new ComponentName(c,BackupJob.class)).setMinimumLatency(3_000).setOverrideDeadline(15*60_000).build();((JobScheduler)c.getSystemService(Context.JOB_SCHEDULER_SERVICE)).schedule(job);}
 public static void scheduleBackups(Context c){JobScheduler jobs=(JobScheduler)c.getSystemService(Context.JOB_SCHEDULER_SERVICE);jobs.cancel(PERIODIC_JOB);if(!prefs(c).getBoolean("backupEnabled",false)){jobs.cancel(KICK_JOB);return;}String frequency=prefs(c).getString("backupFrequency","daily");long period="daily".equals(frequency)?24*60*60_000L:"hourly".equals(frequency)?60*60_000L:15*60_000L;jobs.schedule(new JobInfo.Builder(PERIODIC_JOB,new ComponentName(c,BackupJob.class)).setPersisted(true).setPeriodic(period,Math.max(5*60_000L,period/4)).build());}
 public static void backupNow(Context c){IO.execute(()->maybeBackup(c,true));}
 public static void maybeBackup(Context c,boolean force){synchronized(AppFiles.LOCK){backupCurrentProfile(c,force);}}
 private static void backupCurrentProfile(Context c,boolean force){SharedPreferences p=prefs(c);if(!p.getBoolean("backupEnabled",false))return;Uri created=null;try{if(!folderGranted(c))throw new IOException("Folder access was removed. Choose your backup folder again.");String raw=AppFiles.read(c);if(raw.isEmpty())return;JSONObject workspace=new JSONObject(raw);long revision=workspace.optLong("revision",0),now=System.currentTimeMillis();if(!force){if(revision==p.getLong("backupRevision",-1))return;String frequency=p.getString("backupFrequency","daily");long delay="daily".equals(frequency)?24*60*60_000L:"hourly".equals(frequency)?60*60_000L:0;if(now-p.getLong("backupLastAt",0)<delay)return;}
  JSONObject wrapper=LocalLibrary.backup(c,workspace);byte[] bytes=wrapper.toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>150_000_000)throw new IOException("The backup exceeds 150 MB");Uri tree=Uri.parse(p.getString("backupFolder","")),parent=DocumentsContract.buildDocumentUriUsingTree(tree,DocumentsContract.getTreeDocumentId(tree));String name="LWLS-backup-v2-"+LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMdd-HHmmss"))+"-r"+revision+".json";created=DocumentsContract.createDocument(c.getContentResolver(),parent,"application/json",name);if(created==null)throw new IOException("The folder provider could not create a file");try(OutputStream out=c.getContentResolver().openOutputStream(created,"w")){if(out==null)throw new IOException("Could not open the backup file");out.write(bytes);out.flush();}byte[] check;try(InputStream in=c.getContentResolver().openInputStream(created)){if(in==null)throw new IOException("Could not verify the new backup");check=AppFiles.readBounded(in,150_000_000);}if(!MessageDigest.isEqual(MessageDigest.getInstance("SHA-256").digest(bytes),MessageDigest.getInstance("SHA-256").digest(check)))throw new IOException("Backup verification failed");
  JSONArray old=array(p.getString("backupHistory","[]"));List<JSONObject> history=new ArrayList<>();history.add(new JSONObject().put("id",UUID.randomUUID().toString()).put("uri",created.toString()).put("name",name).put("createdAt",Instant.now().toString()).put("revision",revision).put("bytes",bytes.length));for(int i=0;i<old.length();i++)history.add(old.getJSONObject(i));created=null;int keep=p.getInt("backupKeep",14);boolean cleanup=false;for(int i=history.size()-1;i>=keep;i--){try{if(DocumentsContract.deleteDocument(c.getContentResolver(),Uri.parse(history.get(i).getString("uri"))))history.remove(i);else cleanup=true;}catch(Exception e){cleanup=true;}}JSONArray kept=new JSONArray();for(int i=0;i<Math.min(200,history.size());i++)kept.put(history.get(i));p.edit().putString("backupHistory",kept.toString()).putLong("backupRevision",revision).putLong("backupLastAt",now).putString("backupLastName",name).putString("backupError",cleanup?"Backup saved, but some older files could not be removed.":"").apply();
 }catch(Exception e){if(created!=null)try{DocumentsContract.deleteDocument(c.getContentResolver(),created);}catch(Exception ignored){}p.edit().putString("backupError",e.getMessage()==null?"The backup could not be saved":e.getMessage()).apply();}}
 public static String readHistory(Context c,String id)throws Exception{JSONArray history=array(prefs(c).getString("backupHistory","[]"));for(int i=0;i<history.length();i++){JSONObject row=history.getJSONObject(i);if(id.equals(row.optString("id")))try(InputStream in=c.getContentResolver().openInputStream(Uri.parse(row.getString("uri")))){if(in==null)break;return new String(AppFiles.readBounded(in,150_000_000),StandardCharsets.UTF_8);}}throw new IOException("This recovery file is unavailable. Import it from the folder instead.");}
 public static JSONObject status(Context c){try{SharedPreferences p=prefs(c);JSONArray history=array(p.getString("backupHistory","[]")),safe=new JSONArray();for(int i=0;i<Math.min(60,history.length());i++){JSONObject row=new JSONObject(history.getJSONObject(i).toString());row.remove("uri");safe.put(row);}return new JSONObject().put("platform","android").put("reminder",reminder(c).put("allowed",notificationsAllowed(c)).put("nextAt",p.getLong("reminderNext",0)).put("error",p.getString("reminderError",""))).put("backup",new JSONObject().put("enabled",p.getBoolean("backupEnabled",false)).put("connected",folderGranted(c)).put("folderName",p.getString("backupFolderName","")).put("frequency",p.getString("backupFrequency","daily")).put("keep",p.getInt("backupKeep",14)).put("lastAt",p.getLong("backupLastAt",0)).put("lastName",p.getString("backupLastName","")).put("error",p.getString("backupError","")).put("history",safe)).put("widget",new JSONObject().put("pinSupported",AppWidgetManager.getInstance(c).isRequestPinAppWidgetSupported()).put("count",AppWidgetManager.getInstance(c).getAppWidgetIds(new ComponentName(c,LearningWidget.class)).length));}catch(Exception e){return new JSONObject();}}
}
